module tickgen #(parameter int N = 4) (
  input  logic clk,
  input  logic rst,
  output logic tick
);

  logic [$clog2(N + 1):0] cnt;

  always_ff @(posedge clk) begin
    if (rst) begin
      cnt  <= '0;
      tick <= 1'b0;
    end else if (cnt == N - 1) begin
      cnt  <= '0;
      tick <= 1'b1;
    end else begin
      cnt  <= cnt + 1'b1;
      tick <= 1'b0;
    end
  end

endmodule

key.harness:
`timescale 1ns/1ps

// The grading testbench. Three values of N at once, two gaps measured
// for each, the width of a tick, silence while reset is high, and the
// whole thing again after a reset in the middle of a period.
//
// Relative measurements only: nothing here depends on which edge a
// correct design chooses to put its first tick on.
module tb;

  logic clk = 1'b0;
  always #5 clk = ~clk;

  logic rst = 1'b1;
  logic k2, k3, k7;

  tickgen #(.N(2)) d2 (.clk(clk), .rst(rst), .tick(k2));
  tickgen #(.N(3)) d3 (.clk(clk), .rst(rst), .tick(k3));
  tickgen #(.N(7)) d7 (.clk(clk), .rst(rst), .tick(k7));

  int phase = 0;     // 0 = first window, 1 = after the mid-stream reset

  int e = 0;
  int a1 = -1, a2 = -1, a3 = -1;   // N = 2
  int b1 = -1, b2 = -1, b3 = -1;   // N = 3
  int c1 = -1, c2 = -1, c3 = -1;   // N = 7
  int run3 = 0, widest3 = 0;
  int quiet = 1;

  int f = 0;                       // edges in the second window
  int g1 = -1, g2 = -1, g3 = -1;   // N = 3, after the reset

  always @(posedge clk) begin
    if (rst) begin
      if (k2 || k3 || k7) quiet <= 0;
    end else if (phase == 0) begin
      e <= e + 1;
      if (k2) begin
        if      (a1 < 0) a1 <= e + 1;
        else if (a2 < 0) a2 <= e + 1;
        else if (a3 < 0) a3 <= e + 1;
      end
      if (k7) begin
        if      (c1 < 0) c1 <= e + 1;
        else if (c2 < 0) c2 <= e + 1;
        else if (c3 < 0) c3 <= e + 1;
      end
      if (k3) begin
        if      (b1 < 0) b1 <= e + 1;
        else if (b2 < 0) b2 <= e + 1;
        else if (b3 < 0) b3 <= e + 1;
        run3    <= run3 + 1;
        widest3 <= (run3 + 1 > widest3) ? run3 + 1 : widest3;
      end else begin
        run3 <= 0;
      end
    end else begin
      f <= f + 1;
      if (k3) begin
        if      (g1 < 0) g1 <= f + 1;
        else if (g2 < 0) g2 <= f + 1;
        else if (g3 < 0) g3 <= f + 1;
      end
    end
  end

  initial begin
    $dumpfile("grade.vcd");
    $dumpvars(0, tb);

    @(negedge clk);
    @(negedge clk);
    rst = 1'b0;

    repeat (30) @(posedge clk);
    #1;

    $display("CHECK quiet_in_reset 1 %0d AT %0d", quiet, $time);
    $display("CHECK n2_seen 1 %0d AT %0d", (a3 > 0), $time);
    $display("CHECK n2_period 2 %0d AT %0d", a2 - a1, $time);
    $display("CHECK n2_period_again 2 %0d AT %0d", a3 - a2, $time);
    $display("CHECK n3_period 3 %0d AT %0d", b2 - b1, $time);
    $display("CHECK n3_period_again 3 %0d AT %0d", b3 - b2, $time);
    $display("CHECK n7_period 7 %0d AT %0d", c2 - c1, $time);
    $display("CHECK n7_period_again 7 %0d AT %0d", c3 - c2, $time);
    $display("CHECK n3_one_cycle 1 %0d AT %0d", widest3, $time);

    // Reset in the middle of a period, then measure it all again.
    @(negedge clk);
    phase = 1;
    rst   = 1'b1;
    @(negedge clk);
    rst   = 1'b0;

    repeat (14) @(posedge clk);
    #1;

    $display("CHECK restarts_after_reset 1 %0d AT %0d", (g3 > 0), $time);
    $display("CHECK n3_period_after_reset 3 %0d AT %0d", g2 - g1, $time);
    $display("DONE 11");
    $finish;
  end

endmodule
